-- Suite-columns backfill (2026-07-15), one-off data migration.
-- Runs recorded by run_query_suites.py before suite_name/suite_case_id
-- existed are linked back to their suite entry by exact query text: the
-- runner always sent the suite's query verbatim from a test_ session, and
-- query texts are unique across the four suite files (asserted at
-- generation time). Already-linked rows (suite_name set) are left alone,
-- so re-running is safe.
-- Generated from the suite JSONs (evals/suites/) — regenerate rather than edit.
--
-- Apply with: make postgres-query FILE=db/commands/migrations/2026_07_15_backfill_suite_columns.sql
BEGIN;

